import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, Mesh, Object3D } = ctx.THREE;

  const root = new Group();
  root.position.set(-1.25, -1.1, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  let meshGroup = null;
  let primitiveResults = [];

  // Load GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    meshGroup = gltf.scene;
    root.add(meshGroup);

    // Ensure all meshes have proper PBR materials (machined-metal aesthetic)
    meshGroup.traverse((node) => {
      if (node.isMesh && node.material) {
        // If material lacks metalness/roughness, upgrade to StandardNodeMaterial
        if (!node.material.metalness !== undefined) {
          const mat = new MeshStandardNodeMaterial({
            color: node.material.color || 0xffffff,
            metalness: 0.5,
            roughness: 0.6,
            clearcoat: 0.15,
            clearcoatRoughness: 0.3
          });
          node.material = mat;
        }
      }
    });
  });

  // Apply cinematic primitives
  const applyPrimitives = () => {
    if (!meshGroup) return;

    const cinematicPrimitives = config.cinematicPrimitives || [];

    for (const prim of cinematicPrimitives) {
      if (prim.name === 'parallax-scroll') {
        const result = ctx.primitives['parallax-scroll'](root, {
          intensity: prim.params?.intensity ?? 0.4,
          trigger: prim.trigger
        });
        primitiveResults.push(result);
      } else if (prim.name === 'magnetic-cursor') {
        const result = ctx.primitives['magnetic-cursor'](root, {
          radius: prim.params?.radius ?? 1.2,
          strength: prim.params?.strength ?? 0.35,
          trigger: prim.trigger
        });
        primitiveResults.push(result);
      }
    }
  };

  // Defer primitive application until mesh is loaded
  const checkMeshReady = setInterval(() => {
    if (meshGroup) {
      clearInterval(checkMeshReady);
      applyPrimitives();
    }
  }, 16);

  // Interaction handlers
  const handlers = {};

  handlers.hover = () => {
    gsap.to(root.position, {
      y: root.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  handlers.unhover = () => {
    gsap.to(root.position, {
      y: -1.1,
      duration: 0.9,
      ease: 'power4.out',
      overwrite: 'auto'
    });
  };

  handlers.click = () => {
    ctx.emit('navigate', { to: 'hub-features' });
  };

  root.userData.handlers = handlers;

  // Cleanup function
  root.userData.cleanup = () => {
    clearInterval(checkMeshReady);

    // Kill all GSAP timelines on this object
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.rotation);
    gsap.killTweensOf(root.scale);

    // Cleanup primitives
    for (const result of primitiveResults) {
      if (result?.cleanup) {
        result.cleanup();
      }
    }

    // Dispose materials and geometries
    root.traverse((node) => {
      if (node.isMesh) {
        if (node.geometry) node.geometry.dispose();
        if (node.material) {
          if (Array.isArray(node.material)) {
            node.material.forEach(mat => mat.dispose?.());
          } else {
            node.material.dispose?.();
          }
        }
      }
    });
  };

  return root;
}
